def formatear_pesos(valor):
    return f"${valor:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")

def guardar_factura_alquiler(alquiler_id, archivo):
    """Guarda/reemplaza la factura asociada a un alquiler y devuelve su ruta."""
    if archivo is None:
        return None
    nombre_original = os.path.basename(archivo.name).replace(" ", "_")
    ruta = os.path.join(DIR_FACTURAS, f"alquiler_{alquiler_id}_{nombre_original}")
    with open(ruta, "wb") as f:
        f.write(archivo.getbuffer())
    return ruta

def obtener_tarifas_maquina(maquina_id, precio_dia=0):
    """Devuelve una lista de 30 precios, uno por cada duración (1 a 30 días)."""
    conn = obtener_conexion()
    filas = conn.cursor().execute(
        "SELECT dias, precio FROM tarifas_maquinas WHERE maquina_id=? ORDER BY dias",
        (maquina_id,),
    ).fetchall()
    conn.close()

    tarifas = {dias: precio for dias, precio in filas}
    return [tarifas.get(d, (precio_dia or 0) * d) for d in range(1, 31)]

def guardar_tarifas_maquina(maquina_id, precios):
    """Guarda/reemplaza las tarifas de una máquina para 1 a 30 días."""
    conn = obtener_conexion()
    cur = conn.cursor()
    cur.execute("DELETE FROM tarifas_maquinas WHERE maquina_id=?", (maquina_id,))
    cur.executemany(
        "INSERT INTO tarifas_maquinas (maquina_id, dias, precio) VALUES (?, ?, ?)",
        [(maquina_id, dias, float(precio)) for dias, precio in enumerate(precios, start=1)],
    )
    conn.commit()
    conn.close()

CATALOGO_VERSION = "12-07-2026-redondeo-v1"

def inicializar_tarifas_catalogo():
    """Compatibilidad: carga las tarifas si una máquina todavía no las tiene."""
    conn = obtener_conexion()
    cur = conn.cursor()
    for nombre, precios in PRECIOS_MAQUINAS.items():
        fila = cur.execute(
            "SELECT id FROM maquinas WHERE lower(trim(nombre))=lower(trim(?))",
            (nombre,),
        ).fetchone()
        if not fila:
            continue
        maquina_id = fila[0]
        existe = cur.execute(
            "SELECT 1 FROM tarifas_maquinas WHERE maquina_id=? LIMIT 1",
            (maquina_id,),
        ).fetchone()
        if not existe:
            cur.executemany(
                "INSERT INTO tarifas_maquinas (maquina_id, dias, precio) VALUES (?, ?, ?)",
                [(maquina_id, d, float(precio)) for d, precio in enumerate(precios, start=1)],
            )
    conn.commit()
    conn.close()

def sincronizar_catalogo_actualizado():
    """Sincroniza una nueva lista de catálogo una sola vez por versión."""
    conn = obtener_conexion()
    cur = conn.cursor()
    cur.execute(
        "CREATE TABLE IF NOT EXISTS configuracion (clave TEXT PRIMARY KEY, valor TEXT)"
    )
    version = cur.execute(
        "SELECT valor FROM configuracion WHERE clave='catalogo_version'"
    ).fetchone()
    if version and version[0] == CATALOGO_VERSION:
        conn.close()
        return

    for nombre in CATALOGO_MAQUINAS:
        precios = PRECIOS_MAQUINAS[nombre]
        fila = cur.execute(
            "SELECT id FROM maquinas WHERE lower(trim(nombre))=lower(trim(?))",
            (nombre,),
        ).fetchone()

        if fila:
            maquina_id = int(fila[0])
            cur.execute(
                "UPDATE maquinas SET precio_dia=? WHERE id=?",
                (float(precios[0]), maquina_id),
            )
            cur.execute("DELETE FROM tarifas_maquinas WHERE maquina_id=?", (maquina_id,))
        else:
            cur.execute(
                """INSERT INTO maquinas
                   (nombre, modelo, estado, precio_dia, cantidad_total, cantidad_disponible)
                   VALUES (?, ?, 'Disponible', ?, 1, 1)""",
                (nombre, "", float(precios[0])),
            )
            maquina_id = int(cur.lastrowid)

        cur.executemany(
            "INSERT INTO tarifas_maquinas (maquina_id, dias, precio) VALUES (?, ?, ?)",
            [(maquina_id, d, float(precio)) for d, precio in enumerate(precios, start=1)],
        )

    cur.execute(
        "INSERT INTO configuracion (clave, valor) VALUES ('catalogo_version', ?) "
        "ON CONFLICT(clave) DO UPDATE SET valor=excluded.valor",
        (CATALOGO_VERSION,),
    )
    conn.commit()
    conn.close()

def cargar_catalogo_inicial():
    """Inicializa/sincroniza el catálogo actualizado."""
    sincronizar_catalogo_actualizado()

def calcular_precio_por_dias(maquina_id, dias, precio_dia=0):
    """Obtiene el precio total de la máquina para N días."""
    dias = max(1, int(dias))
    tarifas = obtener_tarifas_maquina(maquina_id, precio_dia)
    if dias <= 30:
        return float(tarifas[dias - 1])
    # Para más de 30 días, usa la tarifa del día 30 + precio diario por cada día extra.
    return float(tarifas[29]) + float(precio_dia or 0) * (dias - 30)

def formatear_fecha(valor):
    if not valor:
        return "—"
    try:
        return datetime.strptime(str(valor), "%Y-%m-%d").strftime("%d/%m/%Y")
    except Exception:
        return str(valor)

def actualizar_estado_maquina(cursor, maquina_id):
    fila = cursor.execute(
        "SELECT cantidad_total, cantidad_disponible FROM maquinas WHERE id=?",
        (maquina_id,)
    ).fetchone()
    if not fila:
        return
    total, disponible = int(fila[0] or 0), int(fila[1] or 0)
    if disponible <= 0:
        estado = "En Alquiler"
    elif disponible < total:
        estado = "Parcialmente Alquilada"
    else:
        estado = "Disponible"
    cursor.execute("UPDATE maquinas SET estado=? WHERE id=?", (estado, maquina_id))

def obtener_alquiler_detalles(cursor, alquiler_id):
    return cursor.execute(
        """
        SELECT d.id, d.maquina_id, m.nombre, COALESCE(m.modelo,''), d.cantidad,
               d.precio_unitario, d.subtotal
        FROM detalle_alquiler d
        JOIN maquinas m ON d.maquina_id=m.id
        WHERE d.alquiler_id=?
        ORDER BY m.nombre
        """,
        (alquiler_id,)
    ).fetchall()

# Carpeta para guardar remitos / documentación
DIR_DOCUMENTOS = "documentos_clientes"
if not os.path.exists(DIR_DOCUMENTOS):
    os.makedirs(DIR_DOCUMENTOS)

# Carpeta para guardar facturas asociadas a cada alquiler
DIR_FACTURAS = "facturas_alquileres"
if not os.path.exists(DIR_FACTURAS):
    os.makedirs(DIR_FACTURAS)

def obtener_conexion():
    return sqlite3.connect("alquileres.db")

def inicializar_bd():
    conn = obtener_conexion()
    cursor = conn.cursor()

    cursor.execute(
        """
        CREATE TABLE IF NOT EXISTS ingresos (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            fecha TEXT,
            monto REAL,
            concepto TEXT,
            cuenta TEXT
        )
        """
    )

    cursor.execute(
        """
        CREATE TABLE IF NOT EXISTS clientes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            nombre TEXT NOT NULL,
            apellido TEXT,
            telefono TEXT,
            direccion TEXT,
            documento_path TEXT
        )
    """
    )

    # Migración de tabla clientes
    cursor.execute("PRAGMA table_info(clientes)")
    cols = [c[1] for c in cursor.fetchall()]
    if "apellido" not in cols:
        cursor.execute("ALTER TABLE clientes ADD COLUMN apellido TEXT")
    if "direccion" not in cols:
        cursor.execute("ALTER TABLE clientes ADD COLUMN direccion TEXT")
    if "documento_path" not in cols:
        cursor.execute("ALTER TABLE clientes ADD COLUMN documento_path TEXT")
    if "moroso" not in cols:
        cursor.execute("ALTER TABLE clientes ADD COLUMN moroso INTEGER DEFAULT 0")
    if "cuit" not in cols:
        cursor.execute("ALTER TABLE clientes ADD COLUMN cuit TEXT")

    cursor.execute(
        """
        CREATE TABLE IF NOT EXISTS maquinas (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            nombre TEXT NOT NULL,
            modelo TEXT,
            estado TEXT DEFAULT 'Disponible',
            precio_dia REAL DEFAULT 0,
            cantidad_total INTEGER DEFAULT 1,
            cantidad_disponible INTEGER DEFAULT 1
        )
    """
    )

    cursor.execute("PRAGMA table_info(maquinas)")
    cols_maquinas = [c[1] for c in cursor.fetchall()]
    if "precio_dia" not in cols_maquinas:
        cursor.execute("ALTER TABLE maquinas ADD COLUMN precio_dia REAL DEFAULT 0")
    if "cantidad_total" not in cols_maquinas:
        cursor.execute("ALTER TABLE maquinas ADD COLUMN cantidad_total INTEGER DEFAULT 1")
    if "cantidad_disponible" not in cols_maquinas:
        cursor.execute("ALTER TABLE maquinas ADD COLUMN cantidad_disponible INTEGER DEFAULT 1")
        cursor.execute("UPDATE maquinas SET cantidad_disponible = COALESCE(cantidad_total, 1)")
        
    cursor.execute(
        """
        CREATE TABLE IF NOT EXISTS tarifas_maquinas (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            maquina_id INTEGER NOT NULL,
            dias INTEGER NOT NULL CHECK(dias BETWEEN 1 AND 30),
            precio REAL NOT NULL DEFAULT 0,
            UNIQUE(maquina_id, dias),
            FOREIGN KEY (maquina_id) REFERENCES maquinas (id)
        )
        """
    )

    cursor.execute(
        """
        CREATE TABLE IF NOT EXISTS alquileres (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            cliente_id INTEGER,
            fecha TEXT,
            fecha_devolucion_prevista TEXT,
            fecha_devolucion_real TEXT,
            dias_previstos INTEGER DEFAULT 1,
            estado TEXT DEFAULT 'Activo',
            total REAL DEFAULT 0,
            pagado REAL DEFAULT 0,
            saldo REAL DEFAULT 0,
            observaciones TEXT,
            FOREIGN KEY (cliente_id) REFERENCES clientes (id)
        )
    """
    )

    cols_alq = [c[1] for c in cursor.execute("PRAGMA table_info(alquileres)").fetchall()]
    if "fecha_devolucion_prevista" not in cols_alq:
        cursor.execute("ALTER TABLE alquileres ADD COLUMN fecha_devolucion_prevista TEXT")
    if "fecha_devolucion_real" not in cols_alq:
        cursor.execute("ALTER TABLE alquileres ADD COLUMN fecha_devolucion_real TEXT")
    if "dias_previstos" not in cols_alq:
        cursor.execute("ALTER TABLE alquileres ADD COLUMN dias_previstos INTEGER DEFAULT 1")
    if "total" not in cols_alq:
        cursor.execute("ALTER TABLE alquileres ADD COLUMN total REAL DEFAULT 0")
    if "pagado" not in cols_alq:
        cursor.execute("ALTER TABLE alquileres ADD COLUMN pagado REAL DEFAULT 0")
    if "saldo" not in cols_alq:
        cursor.execute("ALTER TABLE alquileres ADD COLUMN saldo REAL DEFAULT 0")
    if "observaciones" not in cols_alq:
        cursor.execute("ALTER TABLE alquileres ADD COLUMN observaciones TEXT")
    if "forma_pago" not in cols_alq:
        cursor.execute("ALTER TABLE alquileres ADD COLUMN forma_pago TEXT DEFAULT 'Sin pago'" )
    if "factura_path" not in cols_alq:
        cursor.execute("ALTER TABLE alquileres ADD COLUMN factura_path TEXT")

    cursor.execute(
        """
        CREATE TABLE IF NOT EXISTS detalle_alquiler (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            alquiler_id INTEGER NOT NULL,
            maquina_id INTEGER NOT NULL,
            cantidad INTEGER NOT NULL DEFAULT 1,
            precio_unitario REAL NOT NULL DEFAULT 0,
            subtotal REAL NOT NULL DEFAULT 0,
            FOREIGN KEY (alquiler_id) REFERENCES alquileres(id),
            FOREIGN KEY (maquina_id) REFERENCES maquinas(id)
        )
        """
    )

    cols_alq = [c[1] for c in cursor.execute("PRAGMA table_info(alquileres)").fetchall()]
    if "maquina_id" in cols_alq:
        migrables = cursor.execute(
            """
            SELECT a.id, a.maquina_id, a.total, a.dias_previstos
            FROM alquileres a
            WHERE a.maquina_id IS NOT NULL
              AND NOT EXISTS (
                  SELECT 1 FROM detalle_alquiler d WHERE d.alquiler_id = a.id
              )
            """
        ).fetchall()
        for a_id, maquina_id, total, dias_previstos in migrables:
            dias = int(dias_previstos or 1)
            tarifa = cursor.execute(
                "SELECT precio FROM tarifas_maquinas WHERE maquina_id=? AND dias=?",
                (maquina_id, dias),
            ).fetchone()
            precio = float(tarifa[0]) if tarifa else float(total or 0)
            cursor.execute(
                """
                INSERT INTO detalle_alquiler
                    (alquiler_id, maquina_id, cantidad, precio_unitario, subtotal)
                VALUES (?, ?, 1, ?, ?)
                """,
                (a_id, maquina_id, precio, precio),
            )

    cursor.execute(
        """
        UPDATE maquinas
        SET cantidad_total = COALESCE(NULLIF(cantidad_total, 0), 1),
            cantidad_disponible = COALESCE(cantidad_disponible, 1)
        WHERE cantidad_total IS NULL OR cantidad_total=0 OR cantidad_disponible IS NULL
        """
    )

    conn.commit()
    conn.close()


